window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-738c3a7445da1d3a"]={"versions": [{"id": "FIG-738c3a7445da1d3a", "releases": ["R18-10_R4.4.0_R1.5.0", "R19-11", "R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Konzeptionelles Zeitablauf- und Semantikdiagramm zur Veranschaulichung des Logical Execution Time (LET)-Ansatzes innerhalb der AUTOSAR Timing Extensions (AUTOSAR CP). Das Diagramm stellt das Verhältnis zwischen der zeitdeterministischen logischen Abstraktionsebene („Logical“) und dem realen, verdrängenden Ablauf auf Task- und OS-Ebene („Physical“) gegenüber.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm unterscheidet zwei Betrachtungsebenen:</p>\n<ul class=\"fig-list\">\n<li><strong>Logical:</strong> Repräsentiert das LET-Intervall als zusammenhängendes Zeitfenster fester Dauer, begrenzt durch die Zeitpunkte <code>Release</code> (logischer Eingabezeitpunkt) und <code>Terminate</code> (logischer Ausgabezeitpunkt).</li>\n<li><strong>Physical:</strong> Reale Ausführungsebene mit Ereignissen und Zuständen:</li>\n<li>Ereignisse: <code>Activate</code> (Task-Aktivierung), <code>Start</code> (tatsächlicher Rechenbeginn), <code>Terminate</code> (physisches Ausführungsende).</li>\n<li>Zustände (Legende):</li>\n<li><code>Execution</code> (blau ausgefüllter Block): Aktive Rechenzeit auf der CPU.</li>\n<li><code>Suspended</code> (hellblau gepunkteter Block): Unterbrechung/Verdrängung (Preemption/Wartezeit).</li>\n<li><code>Reading/Writing Data Filling/Flushing Buffer</code> (gelb ausgefüllter Block): Pufferoperationen zum Einlesen bzw. Bereitstellen der Kommunikationsdaten.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Logische Ebene:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Mit dem Erreichen des logischen <code>Release</code>-Zeitpunkts stehen die Eingangsdaten fest; die Daten werden in den Puffer eingelesen (<code>Reading/Writing Data Filling/Flushing Buffer</code>).</li>\n<li>Das Intervall <code>Logical Execution Time</code> läuft über eine feste Soll-Dauer bis zum logischen <code>Terminate</code>-Zeitpunkt.</li>\n<li>Am logischen <code>Terminate</code>-Zeitpunkt werden die Ausgangsdaten aus dem Puffer bereitgestellt/geschrieben (<code>Reading/Writing Data Filling/Flushing Buffer</code>).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Physische Ebene:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Synchron zum logischen <code>Release</code> erfolgt das Ereignis <code>Activate</code> der zugehörigen Task/des Runnables.</li>\n<li>Nach einer Latenz startet die physische Ausführung (<code>Start</code>).</li>\n<li>Während des Laufs wechseln Phasen aktiver Ausführung (<code>Execution</code>) und Verdrängung/Unterbrechung (<code>Suspended</code>).</li>\n<li>Die physische Berechnung endet mit <code>Terminate</code> noch vor Ablauf der logischen Zeitspanne.</li>\n<li>Die Ausgabe der Daten an nachfolgende Empfänger bleibt trotz früherem physischen Ausführungsende bis zum Erreichen des logischen <code>Terminate</code>-Punkts verzögert.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li>Gemäß <code>[constr_4558]</code> ist die LET-Semantik ausschließlich auf implizite Sender-Receiver-Kommunikation anwendbar.</li>\n<li>Das LET-Intervall wird im Timing-Modell über eine <code>TimingDescriptionEventChain</code> mit Attribut <code>category = LET_INTERVAL</code> modelliert.</li>\n<li>Das Stimulus-Event (<code>category = LET_RELEASE</code>) markiert den Freigabezeitpunkt, das Response-Event (<code>category = LET_TERMINATE</code>) den Beendigungszeitpunkt; zur Modellierung wird <code>TDEventComplex</code> herangezogen.</li>\n<li>Entwickler müssen sicherstellen, dass die Worst-Case Execution Time (WCET) zuzüglich aller Verdrängungszeiten (<code>Suspended</code>) die definierte <code>Logical Execution Time</code> nicht überschreitet, um einen Deadline-Bruch vor dem <code>Terminate</code>-Zeitpunkt zu verhindern.</li>\n</ul>"}, {"id": "FIG-b86e094601914ca8", "releases": ["R22-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Konzeptionelles Zeitablauf- und Semantikdiagramm zur Veranschaulichung des Logical Execution Time (LET)-Ansatzes innerhalb der AUTOSAR Timing Extensions (AUTOSAR CP). Das Diagramm stellt das Verhältnis zwischen der zeitdeterministischen logischen Abstraktionsebene („Logical“) und dem realen, verdrängenden Ablauf auf Task- und OS-Ebene („Physical“) gegenüber.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm unterscheidet zwei Betrachtungsebenen:</p>\n<ul class=\"fig-list\">\n<li><strong>Logical:</strong> Repräsentiert das LET-Intervall als zusammenhängendes Zeitfenster fester Dauer, begrenzt durch die Zeitpunkte <code>Release</code> (logischer Eingabezeitpunkt) und <code>Terminate</code> (logischer Ausgabezeitpunkt).</li>\n<li><strong>Physical:</strong> Reale Ausführungsebene mit Ereignissen und Zuständen:</li>\n<li>Ereignisse: <code>Activate</code> (Task-Aktivierung), <code>Start</code> (tatsächlicher Rechenbeginn), <code>Terminate</code> (physisches Ausführungsende).</li>\n<li>Zustände (Legende):</li>\n<li><code>Execution</code> (blau ausgefüllter Block): Aktive Rechenzeit auf der CPU.</li>\n<li><code>Suspended</code> (hellblau gepunkteter Block): Unterbrechung/Verdrängung (Preemption/Wartezeit).</li>\n<li><code>Reading/Writing Data Filling/Flushing Buffer</code> (gelb ausgefüllter Block): Pufferoperationen zum Einlesen bzw. Bereitstellen der Kommunikationsdaten.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Logische Ebene:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Mit dem Erreichen des logischen <code>Release</code>-Zeitpunkts stehen die Eingangsdaten fest; die Daten werden in den Puffer eingelesen (<code>Reading/Writing Data Filling/Flushing Buffer</code>).</li>\n<li>Das Intervall <code>Logical Execution Time</code> läuft über eine feste Soll-Dauer bis zum logischen <code>Terminate</code>-Zeitpunkt.</li>\n<li>Am logischen <code>Terminate</code>-Zeitpunkt werden die Ausgangsdaten aus dem Puffer bereitgestellt/geschrieben (<code>Reading/Writing Data Filling/Flushing Buffer</code>).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Physische Ebene:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Synchron zum logischen <code>Release</code> erfolgt das Ereignis <code>Activate</code> der zugehörigen Task/des Runnables.</li>\n<li>Nach einer Latenz startet die physische Ausführung (<code>Start</code>).</li>\n<li>Während des Laufs wechseln Phasen aktiver Ausführung (<code>Execution</code>) und Verdrängung/Unterbrechung (<code>Suspended</code>).</li>\n<li>Die physische Berechnung endet mit <code>Terminate</code> noch vor Ablauf der logischen Zeitspanne.</li>\n<li>Die Ausgabe der Daten an nachfolgende Empfänger bleibt trotz früherem physischen Ausführungsende bis zum Erreichen des logischen <code>Terminate</code>-Punkts verzögert.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li>Gemäß <code>[constr_4558]</code> ist die LET-Semantik ausschließlich auf implizite Sender-Receiver-Kommunikation anwendbar.</li>\n<li>Das LET-Intervall wird im Timing-Modell über eine <code>TimingDescriptionEventChain</code> mit Attribut <code>category = LET_INTERVAL</code> modelliert.</li>\n<li>Das Stimulus-Event (<code>category = LET_RELEASE</code>) markiert den Freigabezeitpunkt, das Response-Event (<code>category = LET_TERMINATE</code>) den Beendigungszeitpunkt; zur Modellierung wird <code>TDEventComplex</code> herangezogen.</li>\n<li>Entwickler müssen sicherstellen, dass die Worst-Case Execution Time (WCET) zuzüglich aller Verdrängungszeiten (<code>Suspended</code>) die definierte <code>Logical Execution Time</code> nicht überschreitet, um einen Deadline-Bruch vor dem <code>Terminate</code>-Zeitpunkt zu verhindern.</li>\n</ul>"}], "trans": [{"from": "FIG-738c3a7445da1d3a", "to": "FIG-b86e094601914ca8", "fr": "R20-11", "tr": "R22-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
